contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // Read the initial observable state of c before the call.
        uint beforePot = c.pot(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        // c.play() requires msg.value == 10 and, when it pays out, sends Ether to the bank and to msg.sender.
        require(amount == 10, "ticket amount must be 10");
        require(address(this).balance >= amount, "not enough balance");

        c.play{value: amount}(); if (__ESBMC_reverted()) return;

        // Read the resulting observable state of c.
        uint afterPot = c.pot(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;

        // General rule: c accepted exactly TICKET_AMOUNT from this call, so its balance at the
        // moment after the call is at least the total it ever received minus payouts; since at
        // most one payout path can execute, the pot after the call is either reset to 0 (payout
        // path) or increased by the ticket amount (no-payout path).
        assert(
            afterPot == 0 ||
            afterPot == beforePot + amount
        );
    }

    receive() external payable {}
}

